import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"Writing Evidence Card: From Tool Polish to Accountable Delivery","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/writing-evidence.en.md","filePath":"public/downloads/worksheets/writing-evidence.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/writing-evidence.en.md"};function i(o,t,s,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="writing-evidence-card-from-tool-polish-to-accountable-delivery" tabindex="-1">Writing Evidence Card: From Tool Polish to Accountable Delivery <a class="header-anchor" href="#writing-evidence-card-from-tool-polish-to-accountable-delivery" aria-label="Permalink to &quot;Writing Evidence Card: From Tool Polish to Accountable Delivery&quot;">​</a></h1><p>Copy this card into a private note for one real writing task at a time. Do not include passwords, client data, unauthorised third-party information, exam answers, or unnecessary personal details. A final version may be public without making the raw draft, feedback, and tool record public.</p><h2 id="_1-define-the-task-reader-and-responsibility" tabindex="-1">1. Define the Task, Reader, and Responsibility <a class="header-anchor" href="#_1-define-the-task-reader-and-responsibility" aria-label="Permalink to &quot;1. Define the Task, Reader, and Responsibility&quot;">​</a></h2><h3 id="writing-evidence-yyyy-mm-dd" tabindex="-1">Writing Evidence - YYYY-MM-DD <a class="header-anchor" href="#writing-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Writing Evidence - YYYY-MM-DD&quot;">​</a></h3><p>Real situation:<br> Task: explain / request / status / decide / narrate / reflect / hand over<br> Audience and relationship:<br> What should they understand, decide, or do afterwards?<br> Genre, length, and deadline:<br> Completion standard:<br> Dictionary / translation / search / AI / human help allowed:<br> Confidentiality, copyright, privacy, and authorship boundary:<br> Final accountable owner:</p><p>When an institution, school, client, or hiring process prohibits assistance, follow the current rule.</p><h2 id="_2-preserve-an-unaided-draft" tabindex="-1">2. Preserve an Unaided Draft <a class="header-anchor" href="#_2-preserve-an-unaided-draft" aria-label="Permalink to &quot;2. Preserve an Unaided Draft&quot;">​</a></h2><p>Raw draft location:<br> First-version time and length:<br> Outline or sources allowed:<br> One sentence the reader should remember:<br> Fact I trust least:<br> Gap most likely hidden by attractive prose:<br> Action I expect from the first version:</p><p>Do not check whole-sentence translations or ask AI for prose first. Keep pauses, repetition, and failed paragraphs as the baseline.</p><h2 id="_3-build-a-fact-and-responsibility-ledger" tabindex="-1">3. Build a Fact and Responsibility Ledger <a class="header-anchor" href="#_3-build-a-fact-and-responsibility-ledger" aria-label="Permalink to &quot;3. Build a Fact and Responsibility Ledger&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim/content</th><th>Type</th><th>Source, version, and location</th><th>Check date</th><th>Confidence</th><th>Publishable?</th><th>What changes it?</th></tr></thead><tbody><tr><td></td><td>fact / number / quotation / experience / inference / advice / other-person data</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>What I knew then and learned later:<br> Third-party content requiring permission:<br> Part still unverifiable:<br> Content to remove or anonymise before delivery:</p><h2 id="_4-preserve-the-document-skeleton" tabindex="-1">4. Preserve the Document Skeleton <a class="header-anchor" href="#_4-preserve-the-document-skeleton" aria-label="Permalink to &quot;4. Preserve the Document Skeleton&quot;">​</a></h2><p>Problem facing the reader:<br> Direct answer:<br> Support 1:<br> Support 2:<br> Concrete example/minimum fact:<br> Limit, counterexample, or unknown:<br> Reader&#39;s next step:</p><table tabindex="0"><thead><tr><th>Paragraph</th><th>Function</th><th>Must keep</th><th>Delete/move</th><th>Reason</th></tr></thead><tbody><tr><td></td><td>context / problem / claim / reason / evidence / example / turn / limit / request / decision / handover</td><td></td><td></td><td></td></tr></tbody></table><h2 id="_5-record-translation-meaning-changes" tabindex="-1">5. Record Translation Meaning Changes <a class="header-anchor" href="#_5-record-translation-meaning-changes" aria-label="Permalink to &quot;5. Record Translation Meaning Changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What I mean</th><th>English first draft</th><th>Translation/tool candidate</th><th>Final decision</th><th>Reason</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Did agent or responsibility change?<br> Was certainty strengthened or weakened?<br> Did negation or condition scope change?<br> Does tone fit the relationship?<br> Non-equivalent institutional/cultural term:<br> Glossary and reviewer:</p><p>Natural, fluent, and faithful are different judgments. The final author explains the trade-off.</p><h2 id="_6-complete-five-revision-passes" tabindex="-1">6. Complete Five Revision Passes <a class="header-anchor" href="#_6-complete-five-revision-passes" aria-label="Permalink to &quot;6. Complete Five Revision Passes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pass</th><th>Main problem</th><th>Before</th><th>After</th><th>Why it changes the task result</th></tr></thead><tbody><tr><td>Task and fact</td><td></td><td></td><td></td><td></td></tr><tr><td>Structure and evidence</td><td></td><td></td><td></td><td></td></tr><tr><td>Sentence and meaning</td><td></td><td></td><td></td><td></td></tr><tr><td>Register and voice</td><td></td><td></td><td></td><td></td></tr><tr><td>Delivery and boundary</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Necessary correction:<br> Ambiguity repair:<br> Register choice:<br> Personal voice retained:<br> Change I rejected because I could not explain it:</p><h2 id="_7-record-feedback-uptake" tabindex="-1">7. Record Feedback Uptake <a class="header-anchor" href="#_7-record-feedback-uptake" aria-label="Permalink to &quot;7. Record Feedback Uptake&quot;">​</a></h2><p>Ask for a retelling before comments:</p><p>Reader&#39;s retold point:<br> Evidence and limits the reader heard:<br> Next step the reader understood:<br> Place requiring guessing:</p><table tabindex="0"><thead><tr><th>Feedback</th><th>Source/relationship</th><th>Category</th><th>Decision</th><th>Reason</th><th>Used in parallel text?</th></tr></thead><tbody><tr><td></td><td>real reader / peer / teacher / editor / AI</td><td>correction / ambiguity / structure / evidence / register / style</td><td>accept / partly / reject / defer</td><td></td><td></td></tr></tbody></table><p>An improved old draft does not prove new-task use. Feedback begins to show transfer when it enters a parallel text.</p><h2 id="_8-record-ai-and-automated-tool-use" tabindex="-1">8. Record AI and Automated Tool Use <a class="header-anchor" href="#_8-record-ai-and-automated-tool-use" aria-label="Permalink to &quot;8. Record AI and Automated Tool Use&quot;">​</a></h2><p>Tool / model / version and date:<br> Draft and sources that existed before use:<br> Request: diagnosis / reader simulation / fact candidate / correction<br> / version comparison / counterexample / other<br> Scope generated or rewritten by the model:<br> Facts, quotations, or sources it may have invented:<br> My item-by-item verification:<br> What I accepted/rejected, and why:<br> Disclosure required for school, client, employer, or reader:<br> Parallel task after closing the tool:</p><p>Model output is a candidate. It does not own authorship or carry final accountability.</p><h2 id="_9-check-asynchronous-delivery" tabindex="-1">9. Check Asynchronous Delivery <a class="header-anchor" href="#_9-check-asynchronous-delivery" aria-label="Permalink to &quot;9. Check Asynchronous Delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Content</th><th>Accepted?</th></tr></thead><tbody><tr><td>One-sentence conclusion/subject</td><td></td><td></td></tr><tr><td>Completed work and evidence location</td><td></td><td></td></tr><tr><td>Risk, block, and unknown</td><td></td><td></td></tr><tr><td>Who decides what by when</td><td></td><td></td></tr><tr><td>Next step, owner, and checkpoint</td><td></td><td></td></tr><tr><td>What happens without a response</td><td></td><td></td></tr><tr><td>Failure, stop, and rollback</td><td></td><td></td></tr><tr><td>Links, attachments, and permissions</td><td></td><td></td></tr></tbody></table><p>Can the reader continue without another meeting?<br> Real response or execution result:<br> Gap that still required oral explanation:</p><h2 id="_10-test-delayed-retention-and-transfer" tabindex="-1">10. Test Delayed Retention and Transfer <a class="header-anchor" href="#_10-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;10. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>What is removed</th><th>Changed condition</th><th>Output</th><th>Result</th></tr></thead><tbody><tr><td>Day 1</td><td>No AI-written prose</td><td>Original task</td><td>Draft and delivery version</td><td></td></tr><tr><td>Days 3-7</td><td>Old sentences and comments removed</td><td>New topic, same genre</td><td>Parallel text</td><td></td></tr><tr><td>Day 14</td><td>Recent feedback and translation removed</td><td>New audience, same information</td><td>Register-transfer text</td><td></td></tr><tr><td>Day 30</td><td>All practice prompts closed</td><td>Real email, report, application, or handover</td><td>Complete delivery</td><td></td></tr></tbody></table><p>Structure and judgment available after seven days:<br> Problem that returned with a new topic:<br> Did whole-sentence translation/full rewrite dependence decrease?<br> Did the reader guess less?<br> One variable for the next cycle:</p><h2 id="_11-score-and-decide-whether-to-sign" tabindex="-1">11. Score and Decide Whether to Sign <a class="header-anchor" href="#_11-score-and-decide-whether-to-sign" aria-label="Permalink to &quot;11. Score and Decide Whether to Sign&quot;">​</a></h2><p>Score 0-2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Leave an independent draft</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Make task, reader, and next step clear</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Separate fact, source, and inference</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Support conclusion with structure and evidence</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Explain translation/AI/feedback changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Let async reader continue or roll back</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Deliver after topic, audience, or genre changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Current version: willing to sign / needs verification / narrow scope / do not deliver<br> Most important evidence:<br> Conclusion I still cannot draw:<br> Smallest next task:<br> Next review date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/6-writing" target="_blank" rel="noreferrer">Writing: From Draft to Verifiable Revision</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/grammar" target="_blank" rel="noreferrer">Grammar</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/4-reading" target="_blank" rel="noreferrer">Reading</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/7-ai" target="_blank" rel="noreferrer">Learning English with AI</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/8-job-search-english" target="_blank" rel="noreferrer">Job-search English</a> | <a href="https://byoungd.github.io/up/en/threads/part-3/4-artifacts-and-delivery" target="_blank" rel="noreferrer">Artifacts</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/writing-evidence" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',43)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
